import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        long MOD = 1000000007L;
        boolean[] visited = new boolean[p];
        long result = 1;

        if (k != 0) {
            int inverse_k = -1;
            if (k == 1) {
                result = p;
            }
            // Find modular inverse of k modulo p
            for (int i = 1; i < p; i++) {
                if ((long) i * k % p == 1) {
                    inverse_k = i;
                    break;
                }
            }
            for (int i = 1; i < p; i++) {
                if (!visited[i]) {
                    visited[i] = true;
                    int x = 1;
                    int j = (int) ((long) k * i % p);
                    int m = inverse_k;
                    while (!visited[j]) {
                        visited[j] = true;
                        x++;
                        m = (int) ((long) m * inverse_k % p);
                        j = (int) ((long) k * j % p);
                    }
                    if (m == 1) {
                        result = (result * p) % MOD;
                    }
                }
            }
        } else {
            for (int i = 1; i < p; i++) {
                result = (result * p) % MOD;
            }
        }
        System.out.println(result);
        sc.close();
    }
}

